import{_ as s,C as a,o as i,c as o,E as n,a2 as r}from"./chunks/framework.Cm6XCzck.js";const m=JSON.parse(`{"title":"What Does a Green Agent Status Actually Mean? What Sutando's Missing Collaborator Progress Reveals About Agent UI Projection Boundaries","description":"","frontmatter":{"title":"What Does a Green Agent Status Actually Mean? What Sutando's Missing Collaborator Progress Reveals About Agent UI Projection Boundaries","date":"2026-08-27","column":"digital-employee","category":"daily","article_type":"comparative-technical-analysis","edition":"research-center","research_question":"Can viewer identity, gateway connectivity, session liveness, execution progress, report arrival, and lifecycle position be represented by one UI status?","summary":"Starting from Sutando's missing collaborator progress, this study treats agent UI status as a projection contract: every label should declare its source, subject, freshness, evidentiary scope, and conflict behavior.","sources":"/en/research/evidence/2026-08-27-runtime-semantics-evidence-pack","project_relevance":"first-party-research","item_id":"RSEM-20260827-03","lifecycle":"Published","cover":"/assets/covers/daily-2026-08-27-agent-ui-status-projection-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"en/digital-employee/2026-08-27-agent-ui-status-projection.md","filePath":"en/digital-employee/2026-08-27-agent-ui-status-projection.md","lastUpdated":1787844262000}`),c={name:"en/digital-employee/2026-08-27-agent-ui-status-projection.md"};function l(d,e,h,u,p,g){const t=a("ArticleCover");return i(),o("div",null,[n(t,{image:"/assets/covers/daily-2026-08-27-agent-ui-status-projection-cover.png",kicker:"Digital Employee · Engineering Research",title:"What Does a Green Agent Status Actually Mean? What Sutando's Missing Collaborator Progress Reveals About Agent UI Projection Boundaries",summary:"Status is not a source of truth; it is a projection of underlying facts. A reliable agent console should say where each status comes from, what object and time window it covers, and what it explicitly cannot establish.",version:"RSEM-20260827-03",status:"Engineering Research · 2026-08-27",languageHref:"/zh/digital-employee/2026-08-27-agent-ui-status-projection",languageLabel:"中文"}),e[0]||(e[0]=r(`<h1 id="what-does-a-green-agent-status-actually-mean-what-sutando-s-missing-collaborator-progress-reveals-about-agent-ui-projection-boundaries" tabindex="-1">What Does a Green Agent Status Actually Mean? What Sutando&#39;s Missing Collaborator Progress Reveals About Agent UI Projection Boundaries <a class="header-anchor" href="#what-does-a-green-agent-status-actually-mean-what-sutando-s-missing-collaborator-progress-reveals-about-agent-ui-projection-boundaries" aria-label="Permalink to &quot;What Does a Green Agent Status Actually Mean? What Sutando&#39;s Missing Collaborator Progress Reveals About Agent UI Projection Boundaries&quot;">​</a></h1><p>A collaborator was doing real work in a live session and updating the system&#39;s progress file. The team still saw no progress.</p><p>The network was not down. The agent had started. Progress data existed. The failure came from a seemingly reasonable predicate: the UI asked whether the actor was the owner, and non-owners were excluded from progress streaming.</p><p>That is the public counterexample described in Sutando&#39;s open <a href="https://github.com/sonichi/sutando/pull/3432" target="_blank" rel="noreferrer">PR #3432</a>. The original <code>should_stream_task()</code> gate allowed only owners. Its rationale was not absurd: ordinary non-owner team tasks run in a read-only sandbox, do not update <code>core-status.json</code>, and therefore have no live step to stream. The defect was that collaborators were an explicit exception to that execution model. They ran with normal capabilities and did write status, yet the UI still treated &quot;not owner&quot; as equivalent to &quot;no live execution.&quot;</p><p>The error was therefore deeper than a missing progress bar. It was a <strong>fact substitution</strong>:</p><blockquote><p><strong>role / access identity was used as a proxy for execution placement and live progress existence.</strong></p></blockquote><p>The proposed fix is small. <code>team + collaborator</code> changes from false to true; an ordinary team task remains false; owner remains true. Four regression cases cover the distinction. The author also preserves an important limitation: a real post-restart bridge round trip has not yet been witnessed, so the PR remained open when this article was checked.</p><p>That small defect exposes a larger design question:</p><blockquote><p><strong>When an agent console says online, executing, progressing, or completed, what fact is each label actually asserting?</strong></p></blockquote><h2 id="_1-ui-status-is-not-a-source-of-truth-it-is-a-projection-contract" tabindex="-1">1. UI status is not a source of truth; it is a projection contract <a class="header-anchor" href="#_1-ui-status-is-not-a-source-of-truth-it-is-a-projection-contract" aria-label="Permalink to &quot;1. UI status is not a source of truth; it is a projection contract&quot;">​</a></h2><p>Agent consoles often compress several lower-level facts into a single <code>status</code>. Those facts come from different sources, refer to different objects, and expire on different time windows:</p><table tabindex="0"><thead><tr><th>Fact axis</th><th>The question it actually answers</th><th>What it cannot substitute for</th></tr></thead><tbody><tr><td>Viewer authority</td><td>May this user read the information?</td><td>Where the task is executing</td></tr><tr><td>Gateway connectivity</td><td>Can this browser or phone reach the current runtime?</td><td>Whether a session is still live</td></tr><tr><td>Session liveness</td><td>Does this attempt have fresh, verifiable activity?</td><td>Whether the task will deliver successfully</td></tr><tr><td>Progress</td><td>Has the runtime received interpretable recent work progress?</td><td>Whether the work is correct</td></tr><tr><td>REPORT arrival</td><td>Has execution produced a formal report artifact?</td><td>Whether the report has been accepted</td></tr><tr><td>Lifecycle</td><td>Is the task in inbox / active / review / done?</td><td>Whether every associated evidence record is conflict-free</td></tr></tbody></table><p>These axes can be true independently, and they can disagree.</p><p>A gateway can be online while a managed job heartbeat is stale. A session can be completed while its formal REPORT has not arrived. A workflow can be <code>done</code> while an audit association remains in conflict. A viewer can be authorized to see a task without being its executor.</p><p>A reliable UI should therefore be modeled as:</p><p><strong>underlying fact → explicit projection rule → user-facing status</strong></p><p>not:</p><p><strong>user-facing color → inferred system truth</strong></p><p>The first model requires the UI to explain its evidence. The second turns green into an unbounded conclusion with no clear provenance.</p><h2 id="_2-why-the-sutando-case-is-more-than-a-progress-bug" tabindex="-1">2. Why the Sutando case is more than a progress bug <a class="header-anchor" href="#_2-why-the-sutando-case-is-more-than-a-progress-bug" aria-label="Permalink to &quot;2. Why the Sutando case is more than a progress bug&quot;">​</a></h2><p>The immediate issue in #3432 is missing collaborator progress. The more general defect is a mismatch between predicates:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>access tier / owner identity</span></span>
<span class="line"><span>        ↓ incorrectly substituted for</span></span>
<span class="line"><span>execution placement / existence of live progress</span></span></code></pre></div><p>The original rationale was valid for ordinary team tasks but was extended to a collaborator class that did not share the same execution path.</p><p>This kind of projection defect is common because many facts are highly correlated on the happy path: the owner is often the executor; an online gateway often accompanies a live session; a completed session often produces a report quickly; review often follows evidence aggregation.</p><p>But correlation is not identity. The most valuable tests deliberately break those correlations:</p><ul><li>non-owner, but a fresh live session exists;</li><li>gateway online, but the job heartbeat is stale;</li><li>session completed, but the formal REPORT is still missing;</li><li>workflow <code>done</code>, but an evidence association remains conflicted.</li></ul><p>Projection tests should therefore contain <strong>counterexample combinations</strong>, not only normal-path snapshots.</p><h2 id="_3-our-local-audit-five-session-observations-must-remain-distinct-before-presentation" tabindex="-1">3. Our local audit: five session observations must remain distinct before presentation <a class="header-anchor" href="#_3-our-local-audit-five-session-observations-must-remain-distinct-before-presentation" aria-label="Permalink to &quot;3. Our local audit: five session observations must remain distinct before presentation&quot;">​</a></h2><p>Sutando&#39;s PR does not prove that our system contains the same collaborator defect. The useful response is not to map the bug onto another product by analogy, but to inspect our own read paths for collapsed semantics.</p><p>In the session-observation path we audited, five mutually exclusive outputs are disclosed:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>executing_with_progress</span></span>
<span class="line"><span>executing_without_fine_progress</span></span>
<span class="line"><span>session_without_live_execution</span></span>
<span class="line"><span>completed_waiting_report</span></span>
<span class="line"><span>technical_error</span></span></code></pre></div><p>The decision order matters:</p><ol><li>session <code>failed</code> or recovery state <code>session_lost</code> → <code>technical_error</code>;</li><li>session <code>completed</code> while the formal REPORT is not yet written → <code>completed_waiting_report</code>;</li><li>a non-<code>running</code> session is not projected as active execution;</li><li><code>running</code> without live evidence → <code>session_without_live_execution</code>;</li><li><code>running + live</code> is then split by whether fine-grained progress exists.</li></ol><p>That structure rejects several tempting upgrades:</p><ul><li>no fine-grained progress ≠ execution failure;</li><li>existence of a session record ≠ live execution;</li><li>session completed ≠ formally delivered;</li><li>technical error ≠ business rejection.</li></ul><p>One targeted first-party source test contains <strong>five classification assertions</strong>. The earlier shorthand &quot;1/1&quot; meant that one test case passed; it was a poor way to communicate the evidence because it could be mistaken for coverage of only one status. The more faithful statement is: <strong>one targeted test case exercises five disclosed classifications.</strong></p><h2 id="_4-the-public-evidence-can-now-be-rerun-rather-than-merely-read" tabindex="-1">4. The public evidence can now be rerun rather than merely read <a class="header-anchor" href="#_4-the-public-evidence-can-now-be-rerun-rather-than-merely-read" aria-label="Permalink to &quot;4. The public evidence can now be rerun rather than merely read&quot;">​</a></h2><p>To move the central R3 claim out of private source code and prose-only description, we published three deidentified artifacts:</p><ul><li><a href="/joinwell52/assets/evidence/2026-08-27-r3-ui-status-projection-fixture.json">R3 five-case session-observation fixture</a></li><li><a href="/joinwell52/assets/evidence/2026-08-27-r3-ui-status-projection-reader.mjs">R3 UI projection reader</a></li><li><a href="/joinwell52/assets/evidence/2026-08-27-r3-ui-status-projection-check.mjs">R3 check script</a></li></ul><p>The fixture contains five inputs, one for each disclosed semantic class. The public reader reproduces the disclosed decision order. The check script compares <code>actual === expected</code> for all five records and verifies the per-class counts.</p><p>Run:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>node 2026-08-27-r3-ui-status-projection-check.mjs</span></span></code></pre></div><p>Expected output:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;fixture&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;deidentified_runtime_session_observation&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;assertions&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;status&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;PASS&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>The boundary matters: <strong>the public reader is an independent reproducer of the disclosed contract, not the private production source. The five public assertions are not end-to-end certification of desktop UI, PWA, authorization filters, or the complete delivery path.</strong></p><p>What publication adds is inspectability. A reader no longer has to trust the statement that five states exist; the inputs and classification logic can be checked directly.</p><h2 id="_5-conflict-should-be-a-first-class-output-not-noise-the-ui-is-required-to-eliminate" tabindex="-1">5. Conflict should be a first-class output, not noise the UI is required to eliminate <a class="header-anchor" href="#_5-conflict-should-be-a-first-class-output-not-noise-the-ui-is-required-to-eliminate" aria-label="Permalink to &quot;5. Conflict should be a first-class output, not noise the UI is required to eliminate&quot;">​</a></h2><p>A second projection failure happens when sources disagree and the interface silently chooses the most reassuring answer.</p><p>We prefer the opposite rule: <strong>source disagreement is itself a fact worth preserving.</strong></p><p>In the audited paths, for example:</p><ul><li>a missing or conflicting canonical workflow can produce <code>projection_conflict</code> rather than having lifecycle inferred from runtime, REPORT, or acceptance fields;</li><li>a gateway is not published as online when runtime, disk configuration, and context identity disagree;</li><li>a workflow can remain <code>done</code> while an evidence conflict remains visible on a separate axis.</li></ul><p>The principle is simple:</p><blockquote><p><strong>certainty on one fact axis must not erase uncertainty on another.</strong></p></blockquote><p><code>done</code> answers the lifecycle question. <code>evidence conflict</code> answers the evidence-association question. Flattening the two into one status loses information whether the final color is green or red.</p><h2 id="_6-every-green-status-should-declare-at-least-five-things" tabindex="-1">6. Every green status should declare at least five things <a class="header-anchor" href="#_6-every-green-status-should-declare-at-least-five-things" aria-label="Permalink to &quot;6. Every green status should declare at least five things&quot;">​</a></h2><p>A status implemented as only color + text invites components to keep combining unrelated booleans. A stronger design treats each status as a small projection contract with at least these declarations:</p><table tabindex="0"><thead><tr><th>Declaration</th><th>Example</th></tr></thead><tbody><tr><td>Source</td><td><code>Gateway online</code> comes from aligned runtime / disk / context identity, not from a REPORT</td></tr><tr><td>Subject</td><td>Does the status describe a gateway, session, task, or report?</td></tr><tr><td>Freshness</td><td>Which time window or version makes the status valid?</td></tr><tr><td>Establishes / does not establish</td><td>Connection is available; no claim that a session is live or delivery accepted</td></tr><tr><td>Conflict policy</td><td>On source disagreement, return conflict / unknown rather than default green</td></tr></tbody></table><p>Once those declarations exist, &quot;wrong color&quot; bugs become testable semantic questions:</p><ul><li>the viewer is not owner, but has read authority and a fresh local session exists: is progress incorrectly hidden?</li><li>gateway online + stale job heartbeat: can the screen show connection health and execution loss separately?</li><li>session completed + REPORT missing: does the projection stop at waiting-report rather than completed-delivery?</li><li>workflow <code>done</code> + evidence conflict: can both facts remain visible?</li><li>runtime and disk instance identity differ: does the remote page keep presenting the stale instance as current?</li></ul><p>These tests do not require a larger global state machine. They require one discipline: <strong>each condition should answer only the question for which it has evidence.</strong></p><h2 id="_7-green-is-not-a-conclusion-it-is-a-bounded-projection" tabindex="-1">7. Green is not a conclusion; it is a bounded projection <a class="header-anchor" href="#_7-green-is-not-a-conclusion-it-is-a-bounded-projection" aria-label="Permalink to &quot;7. Green is not a conclusion; it is a bounded projection&quot;">​</a></h2><p>Good agent consoles should be simple. Users should not need to read internal traces to understand the system at a glance.</p><p>But simplicity is not achieved by compressing six fact axes into one universal green state. Sutando&#39;s collaborator bug is a compact example of the danger: a rationale can be correct for one execution class and still hide real work when applied to the wrong object.</p><p>Our local evidence supports a bounded conclusion only: session liveness, progress, REPORT waiting, and technical error can be separated before presentation; conflict can remain visible as a distinct axis; and the disclosed classification contract can be tested and publicly reproduced. It does <strong>not</strong> support the stronger claim that every UI, PWA, and authorization combination is already correct.</p><p>So the useful question when a console says &quot;online&quot; or &quot;executing&quot; is not merely whether the status is green. It is:</p><blockquote><p><strong>Which source produced this status, what object does it describe, over what time window is it valid, what does it establish, and what is it explicitly not allowed to establish?</strong></p></blockquote><p>If the interface cannot answer those questions, the status is exercising more authority than its evidence warrants.</p><hr><h2 id="public-evidence" tabindex="-1">Public evidence <a class="header-anchor" href="#public-evidence" aria-label="Permalink to &quot;Public evidence&quot;">​</a></h2><ul><li><a href="/joinwell52/en/research/evidence/2026-08-27-runtime-semantics-evidence-pack">Runtime semantics three-article public evidence pack</a></li><li><a href="/joinwell52/assets/evidence/2026-08-27-r3-ui-status-projection-fixture.json">R3 five-case session-observation fixture</a></li><li><a href="/joinwell52/assets/evidence/2026-08-27-r3-ui-status-projection-reader.mjs">R3 UI projection reader</a></li><li><a href="/joinwell52/assets/evidence/2026-08-27-r3-ui-status-projection-check.mjs">R3 check script</a></li></ul><h2 id="sources-and-evidence-boundary" tabindex="-1">Sources and evidence boundary <a class="header-anchor" href="#sources-and-evidence-boundary" aria-label="Permalink to &quot;Sources and evidence boundary&quot;">​</a></h2><ul><li><a href="https://github.com/sonichi/sutando/pull/3432" target="_blank" rel="noreferrer">Sutando PR #3432</a> was still open when checked. This article uses it only as a public counterexample showing that access tier / role identity cannot safely stand in for execution placement / live-progress existence. The four regression cases are author-reported, and the author explicitly states that a post-restart bridge round trip has not yet been witnessed; this article therefore does not describe the fix as fully production-verified.</li><li>First-party R3 evidence supports the five disclosed session-observation semantics, the corresponding targeted source assertions, and the public deidentified reproducer. The public reader reproduces the disclosed contract rather than publishing private product source, and it does not certify every Web Panel, desktop, PWA, viewer-authority, or permission-filter path.</li><li>The article&#39;s central claim is about <strong>projection boundaries</strong>: viewer authority, gateway connectivity, session liveness, progress, REPORT arrival, lifecycle, and evidence conflict should retain separate provenance and semantics. It is not an overall reliability judgment on Sutando or CodeFlowMu.</li></ul>`,72))])}const f=s(c,[["render",l]]);export{m as __pageData,f as default};
